const $=(s,r=document)=>r.querySelector(s);
const page=location.pathname.split('/').pop().replace('.html','')||'index';
const ph=(label,cls='')=>'<div class="placeholder '+cls+'" role="img" aria-label="'+label+' placeholder"><span>'+label+' / placeholder</span></div>';
const btn=(label,url,secondary=false)=>'<a class="button '+(secondary?'secondary':'')+'" href="'+url+'">'+label+'</a>';
const link=(label,url)=>'<a class="text-link" href="'+url+'">'+label+' &#8594;</a>';
const section=(id,content,shaded=false)=>'<section class="section '+(shaded?'shaded':'')+'" id="'+id+'"><div class="container">'+content+'</div></section>';
const head=(kicker,title,copy='')=>'<div class="section-head"><div><div class="eyebrow">'+kicker+'</div><h2>'+title+'</h2></div>'+(copy?'<p>'+copy+'</p>':'')+'</div>';
const card=(label,title,copy,url,image)=>'<article class="card">'+(image?ph(image,'small'):'')+'<div class="card-body"><span class="tag">'+label+'</span><h3>'+title+'</h3><p>'+copy+'</p>'+link('Explore',url)+'</div></article>';
const hero=(kicker,title,copy,image)=>'<section class="hero"><div class="container '+(image?'split':'')+'"><div><div class="eyebrow">'+kicker+'</div><h1>'+title+'</h1><p class="lead">'+copy+'</p></div>'+(image?ph(image,'large'):'')+'</div></section>';
const cta=()=>section('conversation','<div class="cta"><div><div class="eyebrow">Contact & enquiries</div><h2>Your next chapter starts with a conversation.</h2><p>Connect with our team to explore ELEVATE, our collection and the possibilities ahead.</p></div>'+btn('Make an enquiry','contact.html')+'</div>',true);
const pillars=[
['Health','The foundation of a fulfilled life.','Vitality, strength and longevity shape our ability to live fully. At ELEVATE, we treat them as essentials, creating environments that support an active life and make healthy routines a natural part of every day.'],
['Wellness','A sense of balance, within.','Wellbeing comes from caring for the whole self. From stillness to movement and recovery, our spaces nurture the mind, body and soul, creating room to recharge and reconnect with yourself.'],
['Tribe','Shared values. Meaningful connections.','A sense of belonging grows among people who share values and aspirations. We create welcoming environments where authentic relationships develop, shared energy thrives and individuals feel part of a connected community.'],
['Purpose','Every day, lived with intention.','A fulfilled life has clarity, direction and meaning. Our spaces are designed to inspire intentional living, creating room for the interests, relationships and ambitions that give each day a sense of purpose.'],
['Flow','Life, in a natural rhythm.','True luxury is the ease with which life unfolds. Intelligent design, intuitive technology and thoughtful services work quietly in the background, simplifying routines and giving you more time to move through the day at your own pace.']
];
const pillarCards=(prefix='')=>'<div class="grid five">'+pillars.map((p,i)=>'<article class="pillar"><h3>'+p[0]+'</h3><p>'+p[1]+'</p>'+link('Discover','philosophy.html#'+p[0].toLowerCase())+'</article>').join('')+'</div>';
const projectCard=()=>'<article class="card">'+ph('Mondrian project exterior','small')+'<div class="card-body"><span class="tag">Current development</span><h3>Mondrian Al Marjan Island Beach Residences</h3><p>A hospitality-led residential experience, developed in partnership with Ennismore.</p><div class="project-card-meta"><p><strong>Location</strong><br>Al Marjan Island, Ras Al Khaimah</p><p><strong>Project status</strong><br>Current development</p></div>'+link('Explore the development','mondrian.html')+'</div></article>';
const stories=[
{tag:'Project update',date:'Publication date to be confirmed',title:'ELEVATE presents Mondrian Al Marjan Island Beach Residences',copy:'Discover the architecture, residences and island lifestyle shaping ELEVATE’s flagship development.',url:'article.html',image:'Mondrian project update'},
{tag:'Founder perspective',date:'Publication date to be confirmed',title:'A message from Zeeshaan Shah',copy:'The ELEVATE founder shares the thinking behind the company and its approach to considered living.',url:'leadership.html',image:'Zeeshaan Shah interview'},
{tag:'Wellbeing program',date:'Publication date to be confirmed',title:'Introducing LIVE ELEVATED',copy:'Movement, recovery and connection come together through ELEVATE’s ongoing wellbeing program.',url:'lifestyle-story.html',image:'LIVE ELEVATED gathering'},
{tag:'Press release',date:'Publication date to be confirmed',title:'ELEVATE begins a new chapter in purposeful development',copy:'An introduction to the company, its philosophy and the places it is creating.',url:'announcement.html',image:'ELEVATE announcement'}];
const storyCards=(items=stories)=>items.map(s=>'<article class="card news-card">'+ph(s.image,'small')+'<div class="card-body"><span class="tag">'+s.tag+'</span><p class="meta">'+s.date+'</p><h3>'+s.title+'</h3><p>'+s.copy+'</p>'+link('Read more',s.url)+'</div></article>').join('');
const related=()=>section('related',head('Continue reading','More from ELEVATE')+'<div class="grid">'+storyCards(stories.filter(x=>x.url!==page+'.html').slice(0,3))+'</div>');
const newsletter=(id='newsletter')=>'<form class="newsletter-form" data-kind="newsletter"><label for="'+id+'">Email address</label><div class="newsletter"><input id="'+id+'" type="email" name="email" placeholder="Your email address" required autocomplete="email"><button type="submit">Subscribe</button></div><label class="check"><input type="checkbox" required><span>I agree to receive ELEVATE news and have read the <a href="privacy.html">Privacy Policy</a>.</span></label><div class="form-result" role="status" hidden></div></form>';
const field=(id,label,html,full=false)=>'<div class="field '+(full?'full':'')+'"><label for="'+id+'">'+label+'</label>'+html+'</div>';
const input=(id,type,placeholder,required=false)=>'<input id="'+id+'" name="'+id+'" type="'+type+'" placeholder="'+placeholder+'" '+(required?'required':'')+'>';
const select=(id,options)=>'<select id="'+id+'" name="'+id+'">'+options.map(x=>'<option>'+x+'</option>').join('')+'</select>';
const enquiryForm=(project=false)=>'<form class="form enquiry-form" data-kind="enquiry"><div class="eyebrow">'+(project?'Mondrian residences':'Contact ELEVATE')+'</div><h3>'+(project?'Register your interest':'Tell us how we can help')+'</h3><div class="form-grid">'+
field('enquiry-type','Enquiry type *',select('enquiry-type',['Buyer / end-user','Investor','Broker / channel partner','Strategic / hospitality partner','Media / general enquiry']))+
field('project','Relevant project',select('project',project?['Mondrian Al Marjan Island Beach Residences']:['General enquiry','Mondrian Al Marjan Island Beach Residences']))+
field('full-name','Full name *',input('full-name','text','Your full name',true))+
field('email','Email address *',input('email','email','you@example.com',true))+
field('phone','Phone number *',input('phone','tel','Country code and phone number',true))+
field('country','Country / region',input('country','text','Your country or region'))+
field('contact-method','Preferred contact method',select('contact-method',['Email','Phone call','WhatsApp']))+
field('request','What would you like to do?',select('request',['Request information','Request a callback','Arrange a consultation / appointment','Check availability']))+
field('preferred-date','Preferred callback / appointment date',input('preferred-date','date',''))+
field('preferred-time','Preferred time (UAE time)',select('preferred-time',['No preference','Morning: 09:00 - 12:00','Afternoon: 12:00 - 17:00']))+
(project?field('residence-interest','Residence interest',select('residence-interest',['Please advise me','Residence type A','Residence type B','Residence type C']),true):'')+
field('message','Your message','<textarea id="message" name="message" placeholder="Tell us what interests you, or share your questions."></textarea>',true)+
'<div class="field full"><label class="check"><input type="checkbox" name="consent" required><span>I agree to be contacted about my enquiry and acknowledge the <a href="privacy.html">Privacy Policy</a>. *</span></label><label class="check"><input type="checkbox" name="marketing"><span>I would also like to receive occasional ELEVATE updates (optional).</span></label><button type="submit">Submit enquiry &#8594;</button></div></div><div class="form-result" role="status" tabindex="-1" hidden></div></form>';
const pages={};
pages.index={title:'Home',body:
hero('ELEVATE / A philosophy of living','A more considered<br>way of living.','Thoughtfully designed environments that bring together architecture, wellbeing, meaningful connection and lifestyle.','Brand film / wide cinematic visual')+
section('discover','<div class="split"><div><div class="eyebrow">Discover ELEVATE</div><h2>Beyond a home.<br>A foundation for life.</h2><p>ELEVATE is a UAE-based developer creating premium residential spaces for modern, purposeful living. Our story begins with people and the ways they want to live.</p><p>As our collection grows, one idea remains at its heart: considered environments can help everyday life feel more connected and fulfilling.</p>'+link('Our story','our-story.html')+'</div>'+ph('Architectural detail')+'</div>')+
section('featured','<div class="split">'+ph('Mondrian beachfront project','large')+'<div><div class="eyebrow">Featured development / Ras Al Khaimah</div><h2>Mondrian Al Marjan Island Beach Residences</h2><p>A distinctive residential experience developed in partnership with Ennismore, bringing design and hospitality together on Al Marjan Island.</p><div class="actions">'+btn('Discover Mondrian','mondrian.html')+btn('Explore the collection','developments.html',true)+'</div></div></div>')+
section('philosophy',head('Our philosophy','Five pillars. One way of living.','Health, Wellness, Tribe, Purpose and Flow guide the environments and experiences we create.')+pillarCards('philosophy.html'),true)+
section('founder-preview','<div class="split"><div><div class="eyebrow">Our Founder</div><h2>Zeeshaan Shah</h2><p class="lead">A long-term vision for places that contribute to life.</p><p>Zeeshaan founded ELEVATE with the belief that residential development can create a stronger foundation for how people live, connect and grow.</p><div class="actions">'+btn('Meet our founder','leadership.html')+btn('A message from Zeeshaan Shah','leadership.html#message',true)+'</div></div>'+ph('Zeeshaan Shah portrait','portrait')+'</div>')+
section('partners',head('Partners & collaborators','Shared expertise. One considered vision.')+'<div class="partner-grid">'+[['Ennismore','Hospitality partner'],['Gensler','Architecture and design'],['Begman Design House','Interior design']].map(x=>'<article class="partner-card">'+ph(x[0]+' identity','small')+'<div><span class="tag">'+x[1]+'</span><h3>'+x[0]+'</h3></div></article>').join('')+'</div>',true)+
section('latest',head('News','The latest from ELEVATE.',link('View all news','news.html'))+'<div class="grid">'+storyCards(stories.slice(0,3))+'</div>')+cta()};
pages['our-story']={title:'Our Story',body:
hero('Our Story','Developing spaces.<br>Shaping possibilities.','ELEVATE creates places that give people a stronger foundation for living well.','ELEVATE brand / architecture')+
section('who-we-are','<div class="split"><div><div class="eyebrow">Company introduction</div><h2>A developer guided by how people live.</h2><p>ELEVATE is a UAE-based real estate developer focused on thoughtfully designed, lifestyle-led residential environments. We look beyond individual buildings to consider how architecture, wellbeing, hospitality and community can support a fuller everyday life.</p><p>Backed by the capabilities and long-term perspective of One Group, ELEVATE brings together specialist partners around a clear residential vision.</p></div>'+ph('ELEVATE company and background')+'</div>')+
section('approach','<div class="split">'+ph('Design process and lived experience')+'<div><div class="eyebrow">Vision & Approach</div><h2>Purpose informs every decision.</h2><p>Our approach begins with lived experience, shaping architecture, shared spaces and service around the ways people want to move, restore, connect and belong.</p>'+link('Explore Vision & Approach','vision-approach.html')+'</div></div>',true)+
section('founder','<div class="split"><div><div class="eyebrow">Our Founder</div><h2>Zeeshaan Shah</h2><p>Zeeshaan founded ELEVATE to create residential environments with lasting relevance: places shaped by clarity of purpose, trusted collaboration and an understanding of everyday life.</p>'+link('Read Zeeshaan’s story','leadership.html')+'</div>'+ph('Zeeshaan Shah portrait','portrait')+'</div>')};
pages['vision-approach']={title:'Vision & Approach',parent:'Our Story',body:
hero('Our Story / Vision & Approach','Purpose informs<br>every decision.','Our approach combines architectural thinking, wellbeing and hospitality to create residential environments with enduring relevance.','Design process / spatial study')+
section('vision',head('Our vision','Create places that contribute to life.')+'<p>We start by asking what a place can make possible: a healthier routine, a meaningful connection, a quieter moment or a more intuitive day. These questions guide the experience as much as the built environment.</p>')+
section('environments','<div class="split">'+ph('Purposeful living environment')+'<div><div class="eyebrow">Development approach</div><h2>Designing around lived experience.</h2><p>From the relationship between private and shared spaces to the rhythm of arrival, every layer is considered as part of a complete residential experience.</p></div></div>',true)+
section('architecture','<div class="split"><div><div class="eyebrow">Architecture & considered design</div><h2>Clarity, proportion and attention to detail.</h2><p>Architecture and interiors should work together. We consider natural light, thoughtful circulation, material character and a sense of place as part of a coherent whole.</p></div>'+ph('Architecture / interior detail')+'</div>')+
section('wellbeing','<div class="split">'+ph('Wellbeing / shared space')+'<div><div class="eyebrow">Wellbeing & connection</div><h2>Room for balance. Space for people.</h2><p>Environments for movement, restoration and connection are considered within the wider residential journey, rather than as isolated features.</p></div></div>',true)+
section('hospitality','<div class="split"><div><div class="eyebrow">Hospitality-led residential experiences</div><h2>A thoughtful sense of welcome.</h2><p>Hospitality thinking brings a focus on care, comfort and experience. Mondrian Al Marjan Island Beach Residences expresses this through design, service and the rhythm of arrival.</p>'+link('Explore Mondrian','mondrian.html')+'</div>'+ph('Hospitality / arrival experience')+'</div>')+
section('collection-intro','<div class="cta"><div><div class="eyebrow">Our Collection</div><h2>Ideas made tangible through place.</h2><p>Explore how ELEVATE’s approach comes together at Mondrian Al Marjan Island Beach Residences.</p></div>'+btn('Explore the collection','developments.html')+'</div>',true)};
pages.leadership={title:'Our Founder',parent:'Our Story',body:
hero('Our Story / Our Founder','Zeeshaan Shah','Founder of ELEVATE, shaping a long-term vision for considered living.','Zeeshaan Shah portrait')+
section('founder-profile','<div class="split"><div><div class="eyebrow">Our Founder</div><h2>A clear vision.<br>A personal commitment.</h2><p>Zeeshaan Shah founded ELEVATE with a belief that property should contribute to life beyond the physical home. His perspective brings together development, design, wellbeing and hospitality around the needs and aspirations of residents.</p><p>Through ELEVATE, he is building a collection of distinctive residential environments connected by a shared philosophy and a long-term view of value.</p></div>'+ph('Founder working portrait')+'</div>')+
section('message','<div class="split">'+ph('Founder message / film','large')+'<div><div class="eyebrow">A Message from Zeeshaan Shah</div><h2>Creating places with purpose.</h2><p>Our ambition is to create environments that make everyday life feel more considered, connected and fulfilling. That means thinking beyond the building itself and bringing together the right people, ideas and experiences from the beginning.</p><p>As ELEVATE grows, this commitment will continue to guide every project we create.</p></div></div>',true)};
pages.philosophy={title:'Philosophy',body:
hero('The ELEVATE philosophy','Five pillars.<br>A fuller way of living.','A home is more than a physical space. It is where routines, relationships and ambitions take shape. Our philosophy connects the environments we create with the lives they support.','Philosophy / lifestyle editorial')+
section('pillars',head('Explore the philosophy','Ideas woven into everyday life.')+pillarCards(),true)+
pillars.map((p,i)=>section(p[0].toLowerCase(),'<div class="split">'+(i%2?ph(p[0]+' lifestyle visual'):'')+'<div><div class="eyebrow">Pillar 0'+(i+1)+' / '+p[0]+'</div><h2>'+p[1]+'</h2><p>'+p[2]+'</p><p>'+['From movement to time outdoors, considered environments can make healthy choices a natural part of the day.','A sense of calm can come from light, privacy and spaces that allow people to reconnect with themselves.','Connection grows through places that make meeting, gathering and sharing feel easy and welcoming.','The places we live should provide room for personal ambitions, shared values and a sense of belonging.','From arrival to the transitions between activities, thoughtful design creates an effortless residential rhythm.'][i]+'</p></div>'+(!(i%2)?ph(p[0]+' lifestyle visual'):'')+'</div>',i%2===0)).join('')+
section('in-practice','<div class="split"><div><div class="eyebrow">From philosophy to place</div><h2>Ideas made tangible.</h2><p>Our pillars inform the way we think about architecture, shared spaces, lifestyle and the residential experience. Each development interprets them through its own setting and story.</p>'+btn('Explore our developments','developments.html')+'</div>'+ph('Project / philosophy in practice')+'</div>')+cta()};
pages.developments={title:'Collection',body:
hero('The ELEVATE portfolio','Distinctive places.<br>A shared philosophy.','Explore our current development and the framework for a growing portfolio of purposeful residential environments.','Portfolio / project film')+
section('current',head('Current developments','A new perspective on island living.')+'<div class="grid two">'+projectCard()+'<div class="card"><div class="card-body"><div class="eyebrow">Portfolio introduction</div><h3>Considered in its setting. Connected by purpose.</h3><p>Our current flagship brings together the expressive character of Mondrian and ELEVATE’s approach to residential living.</p><ul class="list"><li><strong>Location</strong><br>Al Marjan Island, Ras Al Khaimah</li><li><strong>Partnership</strong><br>Ennismore / Mondrian</li><li><strong>Development status</strong><br>Approved status to be supplied</li></ul>'+link('Register your interest','mondrian.html#register')+'</div></div></div>')+
section('upcoming',head('Upcoming developments','Looking ahead.')+'<div class="grid two">'+card('Preview / sample','Future development','A reusable project layout for future portfolio additions. No additional launch is confirmed in this prototype.','future-development.html','Future project image')+'<div><h3>A portfolio designed to grow.</h3><p>Future developments will be introduced here when approved project information becomes available.</p>'+btn('Receive portfolio updates','news.html#newsletter',true)+'</div></div>',true)+cta()};
pages.mondrian={title:'Mondrian Al Marjan Island Beach Residences',parent:'Collection',body:
hero('Current development / Ras Al Khaimah','Mondrian Al Marjan Island Beach Residences','A hospitality-led residential experience developed by ELEVATE in partnership with Ennismore.','Immersive project film / exterior')+
'<div class="container"><nav class="side-nav" aria-label="Project sections">'+[['Overview','overview'],['Architecture & interiors','design'],['Residences','residences'],['Lifestyle & amenities','lifestyle'],['Location','location'],['Gallery','gallery'],['Films','project-films'],['Construction updates','construction'],['Brochure','brochure'],['Enquire','register']].map(x=>'<a href="#'+x[1]+'">'+x[0]+'</a>').join('')+'</nav></div>'+
section('overview',head('Project overview','A distinctive expression of island living.')+'<p>Set on Al Marjan Island in Ras Al Khaimah, the project brings together ELEVATE’s philosophy of purposeful living with the character of Mondrian and the hospitality perspective of Ennismore.</p><div class="facts"><div class="fact"><small>Location</small><strong>Al Marjan Island</strong></div><div class="fact"><small>Developer</small><strong>ELEVATE</strong></div><div class="fact"><small>Hospitality partner</small><strong>Ennismore</strong></div><div class="fact"><small>Status</small><strong>To be confirmed</strong></div></div>')+
section('partnership',head('Our partners & collaborations','Expertise brought together around one vision.')+'<div class="partner-grid">'+[['Ennismore','Hospitality partner'],['Gensler','Architecture and design'],['Begman Design House','Interior design']].map(x=>'<article class="partner-card">'+ph(x[0]+' identity','small')+'<div><span class="tag">'+x[1]+'</span><h3>'+x[0]+'</h3></div></article>').join('')+'</div>',true)+
section('design','<div class="split"><div><div class="eyebrow">Architecture & interiors</div><h2>A considered dialogue between place and design.</h2><p>expressive architecture, carefully composed interiors and a thoughtful relationship with the coastal setting create a distinctive residential experience.</p></div>'+ph('Architecture / interiors')+'</div>')+
section('residences',head('Residences','Find a space for your way of living.','Explore a range of residence layouts designed for different ways of living.')+'<label for="residence-type">Explore a residence</label><select class="residence-selector" id="residence-type"><option value="A">Residence type A</option><option value="B">Residence type B</option><option value="C">Residence type C</option></select><div class="split"><div id="floorplan">'+ph('Residence type A / floor plan')+'</div><div><span class="tag">Residence overview</span><h3 id="residence-title">Residence type A</h3><p id="residence-copy">A considered private space with areas for everyday living, rest and connection. Final layouts, dimensions and inventory will be supplied by the project team.</p><ul class="list"><li>Bedrooms & area: approved specifications required</li><li>Views & configuration: subject to residence selection</li><li>Pricing & availability: enquire with the project team</li></ul><div class="actions"><button class="secondary" data-download="Floor plan">Download floor plan</button>'+btn('Enquire about availability','#register')+'</div></div></div>',true)+
section('lifestyle',head('Lifestyle & amenities','Experience beyond your private space.')+'<div class="grid">'+card('Wellbeing & recreation','Room to restore','thoughtfully arranged spaces for movement, relaxation and wellbeing.','philosophy.html#wellness','Wellbeing & recreation')+card('Hospitality','A sense of welcome','A residential experience informed by hospitality, care and attention to detail.','vision-approach.html#hospitality','Hospitality experience')+card('Shared spaces','Connection comes naturally','settings that invite residents to meet, gather and share.','philosophy.html#tribe','Community spaces')+'</div>')+
section('location',head('Location & connectivity','Al Marjan Island, Ras Al Khaimah.')+'<div class="split">'+ph('Location map / nearby destinations','large')+'<div><h3>A coastal setting with a wider world around it.</h3><p>Explore the island setting, local destinations and the lifestyle of Ras Al Khaimah.</p><ul class="list"><li>Al Marjan Island / project setting</li><li>Nearby beaches, hospitality and leisure destinations</li><li>Connected to key destinations across Ras Al Khaimah</li></ul></div></div>',true)+
section('gallery',head('Photography & project films','A closer look at the experience.')+'<div id="gallery-image">'+ph('Gallery 01 / project exterior','large')+'</div><div class="gallery-buttons"><button class="secondary" id="gallery-prev" aria-label="Previous gallery placeholder">Previous</button><span id="gallery-count" aria-live="polite">01 / 04</span><button class="secondary" id="gallery-next" aria-label="Next gallery placeholder">Next</button></div>')+
section('brochure','<div class="cta"><div><div class="eyebrow">Project brochure</div><h2>The story, in more detail.</h2><p>Explore the development, residence concepts and lifestyle through the project brochure.</p></div><button data-download="Project brochure">Download project brochure</button></div>',true)+
section('register','<div class="split" style="align-items:start"><div><div class="eyebrow">Register interest</div><h2>Begin your conversation with us.</h2><p>For buyer or investor enquiries, availability, callbacks and consultations, share your details with our team.</p><div class="actions"><a class="button secondary" href="#register" data-request="Request a callback">Request a callback</a><a class="button secondary" href="#register" data-request="Arrange a consultation / appointment">Arrange a consultation</a><button class="secondary" data-whatsapp>WhatsApp enquiry</button></div><hr><h3>For brokers & channel partners</h3><p>Connect with our team for project information and collaboration.</p>'+link('Broker enquiry','contact.html?type=broker')+'</div>'+enquiryForm(true)+'</div>')};
pages['future-development']={title:'Future Development Template',parent:'Collection',body:
hero('Future development','A new place.<br>The same considered approach.','This page demonstrates how a future development can join the ELEVATE portfolio. It does not announce a confirmed project.','Future project film')+
'<div class="container"><nav class="side-nav" aria-label="Future project sections">'+['Overview','Partnership','Design','Residences','Lifestyle','Location','Gallery','Brochure','Register'].map(x=>'<a href="#'+x.toLowerCase()+'">'+x+'</a>').join('')+'</nav></div>'+
section('overview',head('Project overview & key facts','A distinctive project story.')+'<p>a residential environment shaped by its setting and guided by the ELEVATE philosophy. Approved project name, location, positioning and launch status will replace this content.</p><div class="facts">'+['Location','Developer','Project status','Residence collection'].map(x=>'<div class="fact"><small>'+x+'</small><strong>08 October 2026</strong></div>').join('')+'</div>')+
section('partnership',head('Partnership / optional','A shared project vision.')+'<p>Introduce confirmed project partners and their role in the residential experience. This module may be omitted where no partnership applies.</p>',true)+
section('design','<div class="split"><div><div class="eyebrow">Architecture & interiors</div><h2>A response to its place.</h2><p>architecture, landscape and interiors create a connected living environment. Approved designers, materials and design narratives will complete this section.</p></div>'+ph('Future architecture / interiors')+'</div>')+
section('residences',head('Residences & layouts','A collection of considered spaces.')+'<div class="grid two">'+ph('Future residence image')+ph('Future floor plan')+'</div><div class="actions"><button class="secondary" data-download="Future floor plan">Download floor plan</button>'+btn('Availability enquiry','#register')+'</div>',true)+
section('lifestyle',head('Lifestyle & amenities','The experience around the home.')+'<div class="grid">'+['Wellbeing & recreation','Hospitality experience','Shared spaces & community'].map(x=>'<article class="card">'+ph(x,'small')+'<div class="card-body"><h3>'+x+'</h3><p>A selection of features, amenities and experiences.</p></div></article>').join('')+'</div>')+
section('location','<div class="split">'+ph('Future location map')+'<div><div class="eyebrow">Location & connectivity</div><h2>Introduce the destination.</h2><p>Approved location story, nearby destinations and verified travel times will appear here.</p></div></div>',true)+
section('gallery',head('Photography & films','Project gallery.')+'<div class="grid">'+['Exterior','Interiors','Lifestyle'].map(x=>ph('Future '+x,'small')).join('')+'</div>')+
section('brochure',head('Project brochure','More detail, when available.')+'<p>Approved downloadable materials can be added to the same project template.</p><button data-download="Future project brochure">Download project brochure</button>',true)+
section('register','<div class="split" style="align-items:start"><div><div class="eyebrow">Future project enquiries</div><h2>Stay connected to what comes next.</h2><div class="actions"><a class="button secondary" href="#register" data-request="Request a callback">Request a callback</a><a class="button secondary" href="#register" data-request="Arrange a consultation / appointment">Arrange a consultation</a><button class="secondary" data-whatsapp>WhatsApp enquiry</button></div><p>'+link('Broker enquiry','contact.html?type=broker')+'</p></div>'+enquiryForm()+'</div>')};



pages.developments.body=hero('Collection','Distinctive places.<br>A shared philosophy.','A growing collection of residential environments shaped by their setting and connected by ELEVATE’s approach to living.','Collection / cinematic architecture')+
section('project-listing','<div class="collection-feature">'+ph('Mondrian Al Marjan Island Beach Residences','large')+'<div class="collection-feature-copy"><div class="eyebrow">The Collection / Ras Al Khaimah</div><h2>Mondrian Al Marjan Island Beach Residences</h2><p class="lead">A hospitality-led residential experience on Al Marjan Island, bringing ELEVATE’s philosophy together with the expressive character of Mondrian.</p><dl class="portfolio-project-facts"><div><dt>Location</dt><dd>Al Marjan Island, Ras Al Khaimah</dd></div><div><dt>Collaborators</dt><dd>Ennismore, Gensler and Begman Design House</dd></div></dl><div class="actions">'+btn('Explore Mondrian','mondrian.html')+btn('Register interest','mondrian.html#register',true)+'</div></div></div>',true);
pages.mondrian.body=pages.mondrian.body.replace('<nav class="side-nav" aria-label="Project sections">','<nav class="side-nav" aria-label="Project sections"><a href="#partnership">Partners & collaborations</a>');
pages.mondrian.body=pages.mondrian.body.replace('<section class="section " id="overview">','<div class="container project-quick-actions"><button class="secondary" data-film="Project hero film">Play project film</button>'+btn('Register interest','#register')+'</div><section class="section " id="overview">');
pages.mondrian.body=pages.mondrian.body.replace('href="#register">Enquire about availability','href="#register" data-request="Check availability">Enquire about availability');
