pages.mondrian.body=pages.mondrian.body.replace('<section class="section shaded" id="brochure">',
section('project-films',head('Project films','The experience, in motion.')+'<div class="grid two"><div>'+ph('Project introduction film','small')+'<div class="actions"><button class="secondary" data-film="Project introduction film">Play project film</button></div></div><div>'+ph('Lifestyle & destination film','small')+'<div class="actions"><button class="secondary" data-film="Lifestyle & destination film">Play lifestyle film</button></div></div></div>')+
section('construction',head('Construction updates','Follow the project as it takes shape.')+'<div class="construction-update"><div>'+ph('Latest construction progress','large')+'</div><div><span class="tag">Latest update</span><p class="meta">Update date to be confirmed</p><h3>Progress at Al Marjan Island</h3><p>Verified construction milestones, imagery and delivery information will appear here as approved project updates become available.</p>'+link('View all project news','news.html')+'</div></div>',true)+
'<section class="section shaded" id="brochure">');
pages['future-development'].body=pages['future-development'].body.replace('<section class="section shaded" id="brochure">',
section('project-films',head('Project films','Future project media.')+ph('Future project film','small')+'<div class="actions"><button class="secondary" data-film="Future project film">Play project film</button></div>')+'<section class="section shaded" id="brochure">');
pages['future-development'].body=pages['future-development'].body.replace('href="#register">Availability enquiry','href="#register" data-request="Check availability">Availability enquiry');

pages.news={title:'News',body:
hero('News','The latest from<br>ELEVATE.','Press releases, media coverage, project updates, new launches and founder perspectives in one regularly updated feed.','Editorial / news feature')+
section('stories',head('Latest news','Newest items appear first.')+'<div class="news-feed">'+storyCards()+'</div>')+
section('media-enquiry','<p class="media-enquiry-link"><span>Media enquiries</span> '+link('Contact the ELEVATE team','contact.html?type=media')+'</p>',true)};

const article=(title,category,intro,heading,copy,image)=>hero('News / '+category,title,intro)+section('editorial','<article class="article"><p class="meta">Publication date to be confirmed &middot; '+category+'</p>'+ph(image,'large')+'<h2>'+heading+'</h2><p>'+copy+'</p><p>Our philosophy connects Health, Wellness, Tribe, Purpose and Flow with a considered approach to development. Each project offers an opportunity to express these ideas through architecture, shared spaces and everyday experience.</p>'+ph('Editorial photography','small')+'<div style="margin-top:24px">'+ph('Editorial video / film','small')+'</div>'+'<h2>Explore the story further</h2><p>Explore the ideas, places and experiences shaping ELEVATE’s collection.</p>'+link('Explore Mondrian','mondrian.html')+'<div class="actions">'+btn('Back to news','news.html',true)+'</div></article>')+related();
pages.article={title:'A Closer Look at Island Living',parent:'News',body:article('A closer look at island living.','Project updates','The design and lifestyle ideas behind Mondrian Al Marjan Island Beach Residences.','A residential experience with a sense of place.','Set on Al Marjan Island in Ras Al Khaimah, ELEVATE’s flagship development connects its residential vision with the hospitality perspective of Ennismore and the design-led identity of Mondrian.','Project editorial hero')};
pages.announcement={title:'A New Chapter for Purposeful Living',parent:'News',body:article('A new chapter for purposeful living.','Company announcements','Introducing the ideas at the heart of ELEVATE’s approach to development.','A philosophy that looks beyond property.','ELEVATE creates thoughtfully designed spaces for modern, purposeful living. Our focus is on environments that bring design, wellbeing, connection and lifestyle into a coherent whole.','Company announcement hero')};
pages['lifestyle-story']={title:'Introducing LIVE ELEVATED',parent:'News',body:article('Introducing LIVE ELEVATED.','Wellbeing program','To move. To recover. To connect.','A wellbeing program by ELEVATE.','Twice-monthly gatherings bring together ELEVATE’s community of brokers, partners and team members through movement, recovery and meaningful connection.','LIVE ELEVATED gathering')};
pages['press-coverage']={title:'Press Coverage',parent:'News',body:
hero('News & media / Press coverage','Hospitality meets residential design.','A closer look at how hospitality thinking is shaping contemporary residential experience.')+
section('coverage','<article class="article"><span class="tag">Press coverage item</span><p class="meta">Publication: to be supplied &middot; Publication date: to be supplied</p>'+ph('Publication / coverage image','large')+'<h2>Coverage summary</h2><p>The original article explores the growing connection between hospitality thinking and residential experience, with reference to ELEVATE’s flagship development.</p><h3>Source attribution</h3><p>Publication name, author, original article title and source URL will be inserted after the press item is approved.</p><button class="secondary" data-source>Read original coverage</button><div class="actions">'+btn('Related development','mondrian.html')+btn('Back to news','news.html',true)+'</div></article>')+related()};
pages.contact={title:'Contact & Enquiries',body:
hero('Contact & enquiries','Let’s start<br>a conversation.','Whether you are discovering ELEVATE, exploring a residence or looking to collaborate, our team can help.')+
section('contact','<div class="split" style="align-items:start"><div><div class="eyebrow">Contact ELEVATE</div><h2>Connect with the right team.</h2><p>Choose the enquiry type that best reflects your interest. You can request information, arrange a consultation or ask for a callback.</p><ul class="list"><li><strong>Office</strong><br>Dubai, United Arab Emirates</li><li><strong>Email</strong><br>enquiries&#64;elevate.ae</li><li><strong>Phone</strong><br>+971 4 000 0000</li><li><strong>Office hours</strong><br>Monday to Friday, 9:00–18:00</li></ul><button class="secondary" data-whatsapp>Contact via WhatsApp</button><div style="margin-top:30px">'+ph('Office location map','small')+'</div></div>'+enquiryForm()+'</div>')+
section('project-enquiries',head('Interested in a development?','Go directly to the project.')+'<div class="grid two">'+projectCard()+card('Partners','For brokers & channel partners','Use the enquiry form above to connect about project information and partnership opportunities.','contact.html?type=broker')+'</div>',true)};
const legal=(title,intro,sections)=>hero('Footer & utility / Draft content',title,intro)+section('legal','<article class="article">'+sections.map(x=>'<h2>'+x[0]+'</h2><p>'+x[1]+'</p>').join('')+'</article>');
pages.privacy={title:'Privacy Policy',body:legal('Privacy Policy','How privacy information will be organized for visitors and people who contact ELEVATE.',[
['1. Who we are','The final policy will identify the legal entity operating this website and the contact details for privacy-related enquiries.'],
['2. Information provided by visitors','We may collect the name, email address, phone number, enquiry preferences and messages provided through enquiry and newsletter forms.'],
['3. How information is used','Explain how information supports responses to enquiries, appointment requests, subscribed updates and website improvement.'],
['4. Service providers & lead management','Identify the approved CRM, hosting, analytics and communications providers. The sitemap mentions Zoho; the production integration and routing require confirmation.'],
['5. Cookies & preferences','Essential and optional cookies, their purposes and available controls are described on the Cookie Preferences page.'],
['6. Retention, security & choices','Set out approved retention periods, security practices and the available process for privacy requests, unsubscribing and withdrawing optional consent.'],
['7. Contact & updates','Approved privacy contact details, policy effective date and update process will be supplied before publication.']])+section('preferences',btn('Manage cookie preferences','cookies.html',true))};
pages.terms={title:'Terms of Use',body:legal('Terms of Use','The structure for website-use terms, subject to legal review.',[
['1. Website information','Describe the purpose of the website, the responsible legal entity and the scope of the information published.'],
['2. Project information & availability','Project details, residence specifications, availability and pricing may be updated as developments progress.'],
['3. Intellectual property','Describe ownership and permitted use of website content, photography, project films and downloadable material.'],
['4. Third-party links','Explain the treatment of external publications, social channels and communications links.'],
['5. Acceptable use & enquiries','Describe appropriate website use and the handling of enquiry submissions.'],
['6. Applicable terms & contact','Approved governing terms, jurisdiction, contact information and effective date will be inserted following legal review.']])};
pages.cookies={title:'Cookie Preferences',body:
hero('Footer & utility','Cookie preferences','Choose how optional website technologies may be used. Your preferences are remembered locally in this browser.')+
section('cookie-controls','<div class="preferences"><div class="preference-row"><div><h3>Essential</h3><p>Required for core website functions and remembering your preferences.</p></div><span class="tag">Always on</span></div>'+['Analytics','Marketing'].map(x=>'<div class="preference-row"><div><h3>'+x+'</h3><p>'+ (x==='Analytics'?'Help understand how visitors use the website and where the experience can improve.':'Support approved marketing measurement and campaign experiences.')+'</p></div><label class="check"><input id="cookie-'+x.toLowerCase()+'" type="checkbox"><span>Allow</span></label></div>').join('')+'<div class="actions"><button id="save-cookies">Save my preferences</button><button class="secondary" id="reject-cookies">Reject optional</button><button class="secondary" id="accept-cookies">Accept all</button></div><div class="form-result" id="cookie-result" role="status" hidden></div>'+link('Read privacy policy','privacy.html')+'</div>')};
pages['404']={title:'Page Not Found',body:'<section class="error"><div class="container"><div class="error-code">404</div><div class="eyebrow">Page not found</div><h1>A different path awaits.</h1><p>The page you are looking for may have moved or is no longer available. Explore ELEVATE or get in touch with our team.</p><div class="actions">'+btn('Return home','index.html')+btn('Explore developments','developments.html',true)+btn('Contact us','contact.html',true)+'</div></div></section>'};
pages.sitemap={title:'Sitemap',body:hero('Explore the complete website','Every page.<br>One connected experience.','Use this directory to review all pages and templates. The five philosophy pillars are sections on one page, as specified in the sitemap.')+
section('directory','<div class="directory">'+[
['Brand & company',[['Home','index.html'],['Our Story / About ELEVATE','our-story.html'],['Vision & Approach','vision-approach.html'],['Leadership','leadership.html'],['Philosophy of Living','philosophy.html']]],
['Developments',[['Developments Overview','developments.html'],['Mondrian Project Detail','mondrian.html'],['Future Development Template','future-development.html']]],
['News & media',[['News & Media Overview','news.html'],['Project Article Detail','article.html'],['Company Announcement Detail','announcement.html'],['Brand & Lifestyle Story','lifestyle-story.html'],['Press Coverage Detail','press-coverage.html']]],
['Contact & utility',[['Contact & Enquiries','contact.html'],['Privacy Policy','privacy.html'],['Terms of Use','terms.html'],['Cookie Preferences','cookies.html'],['404 / Not Found','404.html']]],
['Shared interactions',[['Project-specific form','mondrian.html#register'],['Broker enquiry','contact.html?type=broker'],['Media enquiry','contact.html?type=media'],['Newsletter consent & success','news.html#newsletter'],['Gallery navigation','mondrian.html#gallery'],['Residence layout selection','mondrian.html#residences']]],
['Content review',[['Health section','philosophy.html#health'],['Wellness section','philosophy.html#wellness'],['Tribe section','philosophy.html#tribe'],['Purpose section','philosophy.html#purpose'],['Flow section','philosophy.html#flow']]]
].map(([title,items])=>'<div><h3>'+title+'</h3>'+items.map(([t,u])=>'<a href="'+u+'">'+t+' &#8594;</a>').join('')+'</div>').join('')+'</div>')+
section('scope',head('Website structure','What is ready to review.')+'<p>19 linked HTML pages including this directory. All layouts are grayscale, image-led with neutral placeholders, and responsive. The prototype includes enquiry and newsletter confirmation states, category filters, residence selection, gallery navigation, leadership profiles and cookie preferences.</p>',true)};

const aboutItems=[['Our Story','our-story.html','Company introduction and background.'],['Vision & Approach','vision-approach.html','How purpose, architecture, wellbeing and hospitality shape our work.'],['Our Founder','leadership.html','Zeeshaan Shah and the vision behind ELEVATE.']];

const aboutPageNav=()=>'<div class="about-page-nav"><nav class="container about-page-links" aria-label="About ELEVATE pages">'+[
['Our Story','our-story'],['Vision & Approach','vision-approach'],['Our Founder','leadership']
].map(([label,name])=>'<a href="'+name+'.html" '+(page===name?'aria-current="page"':'')+'>'+label+'</a>').join('')+'</nav></div>';
['our-story','vision-approach','leadership'].forEach(name=>{
pages[name].body=pages[name].body.replace('</section>','</section>'+aboutPageNav());
});
pages.philosophy.body=hero('Philosophy','A fuller way<br>of living.','Our philosophy connects the environments we create with the lives they support.','Lifestyle and wellbeing visual')+
section('pillars','<div class="philosophy-intro"><div><div class="eyebrow">Five pillars</div><h2>Five connected ideas.<br>One way of living.</h2></div><p class="lead">Health, Wellness, Tribe, Purpose and Flow work together to support a healthier, more balanced and more meaningful everyday life.</p></div><nav class="pillar-anchor-nav" aria-label="Five pillars">'+pillars.map((p,i)=>'<a href="#'+p[0].toLowerCase()+'"><span>0'+(i+1)+'</span>'+p[0]+'</a>').join('')+'</nav>',true)+
pillars.map((p,i)=>section(p[0].toLowerCase(),'<div class="pillar-story '+(i%2?'reverse':'')+'">'+ph(p[0]+' lifestyle visual','large')+'<div><div class="eyebrow">0'+(i+1)+' / '+p[0]+'</div><h2>'+p[1]+'</h2><p class="lead">'+p[2]+'</p></div></div>',i%2===1)).join('')+
section('in-practice',head('The philosophy in practice','Ideas made tangible at Mondrian.')+'<div class="grid practice-grid">'+[
['Health & Wellness','Dedicated movement, recovery and restorative spaces support an active, balanced island lifestyle.'],
['Tribe & Purpose','Shared amenities and hospitality-led experiences create natural opportunities to gather and belong.'],
['Flow','Intuitive residences, thoughtful services and seamless arrival simplify the rhythm of everyday life.']
].map((x,i)=>'<article class="practice-card">'+ph('Mondrian '+x[0],'small')+'<div><span class="number">0'+(i+1)+'</span><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div></article>').join('')+'</div>')+
section('live-elevated','<div class="live-elevated-intro"><div><div class="eyebrow">LIVE ELEVATED</div><h2>A Wellbeing Program<br>by ELEVATE</h2><p class="lead">To move. To recover. To connect.</p></div><p>LIVE ELEVATED brings our philosophy to life through an ongoing program of twice-monthly gatherings focused on movement, recovery and connection. Bringing together our community of brokers, partners and team members, the program creates time to step away from daily routines, share new experiences and connect with others.</p></div>'+ph('LIVE ELEVATED signature gathering','large')+'<div class="program-grid"><article><span class="eyebrow">Upcoming gatherings</span><h3>What’s next</h3><p>Future movement, recovery and community sessions will appear here as dates are confirmed.</p></article><article><span class="eyebrow">Selected recaps</span><h3>From the program</h3><p>Event imagery, highlights and related stories will build an evolving record of LIVE ELEVATED.</p>'+link('Related stories','news.html')+'</article></div>',true)+
section('collection-intro','<div class="split"><div><div class="eyebrow">Collection</div><h2>Explore places shaped by the philosophy.</h2><p>Mondrian Al Marjan Island Beach Residences brings ELEVATE’s ideas to life through its residences, amenities and hospitality-led experience.</p>'+btn('Discover the collection','developments.html')+'</div>'+ph('Mondrian collection introduction')+'</div>');
pages.sitemap.body=hero('Website structure','Every page.<br>One connected experience.','Browse the revised ELEVATE website hierarchy.')+
section('directory','<div class="directory">'+[
['Home',[['Opening statement','index.html'],['Introduction to ELEVATE','index.html#discover'],['Featured Mondrian','index.html#featured'],['Philosophy','index.html#philosophy'],['Our Founder','index.html#founder-preview'],['Partners & collaborators','index.html#partners'],['News','index.html#latest'],['Contact & enquiries','index.html#conversation']]],
['Our Story',[['Company introduction','our-story.html'],['Vision & Approach','vision-approach.html'],['Our Founder','leadership.html']]],
['Philosophy',[['Five Pillars','philosophy.html#pillars'],['Philosophy in practice','philosophy.html#in-practice'],['LIVE ELEVATED','philosophy.html#live-elevated'],['Collection introduction','philosophy.html#collection-intro']]],
['Collection',[['Collection overview','developments.html'],['Mondrian project experience','mondrian.html']]],
['News',[['News feed','news.html'],['Article / announcement','article.html']]],
['Contact & Utility',[['Contact & Enquiries','contact.html'],['Privacy Policy','privacy.html'],['Terms of Use','terms.html'],['Cookie Preferences','cookies.html'],['404 / Not Found','404.html']]]
].map(([title,items])=>'<div><h3>'+title+'</h3>'+items.map(([t,u])=>'<a href="'+u+'">'+t+' &#8594;</a>').join('')+'</div>').join('')+'</div>')+
section('scope',head('Revised hierarchy','Cleaner navigation and focused content.')+'<p>The public journey now centers on Our Story, Philosophy, Collection, News and Contact Us. Future project templates remain reusable in the source without appearing in public navigation.</p>',true);
const navigationItems=[
['01','Our Story','our-story.html',['our-story','vision-approach','leadership']],
['02','Philosophy','philosophy.html',['philosophy']],
['03','Collection','developments.html',['developments','mondrian','future-development']],
['04','News','news.html',['news','article','announcement','lifestyle-story','press-coverage']]
];
const navigationMarkup='<div class="nav-intro"><div class="eyebrow">Explore ELEVATE</div><p>Discover the company, the philosophy and the places we create.</p></div><div class="nav-links">'+navigationItems.map(t=>'<a href="'+t[2]+'" '+(t[3].includes(page)?'aria-current="page"':'')+'><span>'+t[0]+'</span><strong>'+t[1]+'</strong></a>').join('')+'</div>';

const current=pages[page]||pages['404'];
const header='<a class="skip" href="#main">Skip to content</a><header class="header"><div class="container header-inner"><a class="logo" href="index.html">ELEVATE</a><div class="header-actions"><a class="header-contact" href="contact.html">Contact Us</a><button class="mobile-menu secondary" aria-expanded="false" aria-controls="primary-nav">Menu</button></div><nav class="nav" id="primary-nav" aria-label="Primary navigation">'+navigationMarkup+'</nav></div></header>';
const footer='<footer class="footer"><div class="container"><div class="footer-grid"><div><a class="logo" href="index.html">ELEVATE</a><p>Thoughtfully designed spaces.<br>A philosophy of living.</p><div class="socials"><button class="secondary social-icon" data-social="Instagram" aria-label="Instagram" title="Instagram"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r=".8" fill="currentColor" stroke="none"/></svg></button><button class="secondary social-icon" data-social="LinkedIn" aria-label="LinkedIn" title="LinkedIn"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7.5 10v7M11 17v-7m0 3c0-4 6-4 6 0v4"/><circle cx="7.5" cy="7" r=".8" fill="currentColor" stroke="none"/></svg></button><button class="secondary social-icon" data-social="YouTube" aria-label="YouTube" title="YouTube"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2" y="5" width="20" height="14" rx="4"/><path d="m10 9 6 3-6 3Z" fill="currentColor" stroke="none"/></svg></button></div></div><div><h3>Explore</h3><a href="our-story.html">Our Story</a><a href="vision-approach.html">Vision & Approach</a><a href="leadership.html">Our Founder</a><a href="philosophy.html">Philosophy</a><a href="news.html">News</a></div><div><h3>Collection & enquiries</h3><a href="developments.html">Collection</a><a href="mondrian.html">Mondrian residences</a><a href="mondrian.html#construction">Construction updates</a><a href="mondrian.html#brochure">Project brochure</a><a href="contact.html">Contact Us</a><a href="contact.html?type=broker">Broker enquiries</a></div><div><h3>Stay connected</h3><p>Occasional stories and updates from ELEVATE.</p>'+newsletter('footer-email')+'</div></div><div class="footer-bottom"><span>&copy; 2026 ELEVATE</span><span><a href="privacy.html">Privacy Policy</a> &nbsp; / &nbsp; <a href="terms.html">Terms of Use</a> &nbsp; / &nbsp; <a href="cookies.html">Cookie Preferences</a></span></div></div></footer><dialog id="prototype-dialog" aria-labelledby="dialog-title"><h2 id="dialog-title"></h2><p id="dialog-copy"></p><button id="close-dialog" class="secondary">Close</button></dialog>';
const parentUrls={'Our Story':'our-story.html','Collection':'developments.html','News':'news.html','News & Media':'news.html'};
const crumb=page==='index'?'':'<div class="container breadcrumb"><a href="index.html">Home</a> / '+(current.parent?'<a href="'+parentUrls[current.parent]+'">'+current.parent+'</a> / ':'')+'<span>'+current.title+'</span></div>';
document.title=current.title+' | ELEVATE';
if(!$('#app').hasChildNodes()) $('#app').innerHTML=header+'<main id="main">'+crumb+current.body+'</main>'+footer;
function modal(title,copy){$('#dialog-title').textContent=title;$('#dialog-copy').textContent=copy;$('#prototype-dialog').showModal();}
$('#close-dialog').onclick=()=>$('#prototype-dialog').close();
$('.mobile-menu').onclick=e=>{const open=$('.nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.textContent=open?'Close':'Menu';};
document.querySelectorAll('form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const result=$('.form-result',f);result.hidden=false;result.textContent=f.dataset.kind==='newsletter'?'Thank you for subscribing.':'Thank you. Your enquiry has been received.';if(f.dataset.kind==='enquiry'){result.focus();result.scrollIntoView({behavior:'smooth',block:'center'});}else f.reset();}));
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});let count=0;document.querySelectorAll('.news-card').forEach(c=>{c.hidden=b.dataset.filter!=='All'&&c.dataset.category!==b.dataset.filter;if(!c.hidden)count++;});$('#filter-status').textContent='Showing '+count+' '+(count===1?'story':'stories')+(b.dataset.filter==='All'?'.':' in '+b.dataset.filter+'.');});
document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>modal(b.dataset.download,'This document will be available soon.'));
document.querySelectorAll('[data-whatsapp]').forEach(b=>b.onclick=()=>modal('WhatsApp enquiry','WhatsApp contact will be available soon.'));
document.querySelectorAll('[data-social]').forEach(b=>b.onclick=()=>modal(b.dataset.social,'This social profile will be available soon.'));
document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>modal(b.dataset.profile,'This leadership profile will be available soon.'));
document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>modal('Original press coverage','The original coverage link will be available soon.'));
document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>{$('#request').value=b.dataset.request;if(b.dataset.request==='Check availability'&&$('#residence-interest')&&$('#residence-type')){$('#residence-interest').value='Residence type '+$('#residence-type').value+' - sample';}if(b.dataset.request==='Check availability')$('#full-name').focus();else $('#preferred-date').focus();});
if($('#residence-type'))$('#residence-type').onchange=e=>{const t=e.target.value;$('#residence-title').textContent='Residence type '+t;$('#floorplan').innerHTML=ph('Residence type '+t+' / floor plan');$('#residence-copy').textContent={A:'A considered private space with areas for everyday living, rest and connection.',B:'A sample layout with additional flexibility for shared living and private retreat.',C:'An illustrative larger residence concept with distinct spaces for gathering and rest.'}[t]+' Final layouts, dimensions and inventory will be supplied by the project team.';};
let gallery=0;const galleryLabels=['Project exterior','Residence interiors','Wellbeing & recreation','Island setting'];
function moveGallery(n){gallery=(gallery+n+4)%4;$('#gallery-image').innerHTML=ph('Gallery 0'+(gallery+1)+' / '+galleryLabels[gallery],'large');$('#gallery-count').textContent='0'+(gallery+1)+' / 04';}
if($('#gallery-next')){$('#gallery-next').onclick=()=>moveGallery(1);$('#gallery-prev').onclick=()=>moveGallery(-1);}
if(page==='contact'){const type=new URLSearchParams(location.search).get('type');if(type==='broker')$('#enquiry-type').value='Broker / channel partner';if(type==='media')$('#enquiry-type').value='Media / general enquiry';}
if(page==='future-development'){$('#project').innerHTML='<option>Future developments</option>';}
function readStorage(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}}
function saveStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
if(page==='cookies'){const saved=readStorage('elevate-cookie-preferences');if(saved){$('#cookie-analytics').checked=saved.analytics;$('#cookie-marketing').checked=saved.marketing;}
function saveCookies(mode){if(mode){$('#cookie-analytics').checked=mode==='all';$('#cookie-marketing').checked=mode==='all';}const stored=saveStorage('elevate-cookie-preferences',{analytics:$('#cookie-analytics').checked,marketing:$('#cookie-marketing').checked});$('#cookie-result').hidden=false;$('#cookie-result').textContent=stored?'Your cookie preferences have been saved in this browser. You can change them at any time.':'Your selection is applied for this preview. Browser storage is unavailable, so it cannot be remembered.';}
$('#save-cookies').onclick=()=>saveCookies();$('#reject-cookies').onclick=()=>saveCookies('none');$('#accept-cookies').onclick=()=>saveCookies('all');}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.nav').classList.contains('open')){$('.nav').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');$('.mobile-menu').textContent='Menu';$('.mobile-menu').focus();}});
const tabs=[...document.querySelectorAll('[role=tab]')];
function selectAboutTab(tab,focus=false){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',selected);t.tabIndex=selected?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!selected;});if(focus)tab.focus();}
tabs.forEach((t,i)=>{t.onclick=()=>selectAboutTab(t);t.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i-1+tabs.length)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectAboutTab(tabs[next],true);}};});

document.querySelectorAll('[data-film]').forEach(b=>b.onclick=()=>modal(b.dataset.film,'This film will be available soon.'));

const pillarTabs=[...document.querySelectorAll('.pillar-tabs [role=tab]')];
function activatePillar(tab,focus=false){pillarTabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',active);t.tabIndex=active?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!active;});if(focus)tab.focus();}
function pillarFromHash(){const tab=pillarTabs.find(t=>'#'+t.getAttribute('aria-controls')===location.hash);if(tab)activatePillar(tab);}
pillarTabs.forEach((t,i)=>{t.onclick=()=>{activatePillar(t);history.replaceState(null,'','#'+t.getAttribute('aria-controls'));};t.onkeydown=e=>{let n;if(e.key==='ArrowRight')n=(i+1)%pillarTabs.length;if(e.key==='ArrowLeft')n=(i-1+pillarTabs.length)%pillarTabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=pillarTabs.length-1;if(n!==undefined){e.preventDefault();activatePillar(pillarTabs[n],true);history.replaceState(null,'','#'+pillarTabs[n].getAttribute('aria-controls'));}};});
pillarFromHash();window.addEventListener('hashchange',pillarFromHash);

const portfolioTabs=[...document.querySelectorAll('.portfolio-tabs [role=tab]')];
function activatePortfolio(tab,focus=false){portfolioTabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',active);t.tabIndex=active?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!active;});if(focus)tab.focus();}
function portfolioFromHash(){const tab=portfolioTabs.find(t=>'#'+t.getAttribute('aria-controls')===location.hash);if(tab)activatePortfolio(tab);}
portfolioTabs.forEach((t,i)=>{t.onclick=()=>{activatePortfolio(t);history.replaceState(null,'','#'+t.getAttribute('aria-controls'));};t.onkeydown=e=>{let n;if(['ArrowLeft','ArrowRight'].includes(e.key))n=1-i;if(e.key==='Home')n=0;if(e.key==='End')n=1;if(n!==undefined){e.preventDefault();activatePortfolio(portfolioTabs[n],true);history.replaceState(null,'','#'+portfolioTabs[n].getAttribute('aria-controls'));}};});
portfolioFromHash();window.addEventListener('hashchange',portfolioFromHash);

document.querySelectorAll('[data-leader-linkedin]').forEach(b=>b.onclick=()=>modal('LinkedIn / '+b.dataset.leaderLinkedin,'This profile will be available soon.'));







